package org.concord.biologica.datasupport;import java.awt.Image;public class ShortImageDescription{int 	size;int 	part;public Image 	[]images;boolean	allImages;int 	[]xoffsets;int 	[]yoffsets;public int hcells;int nColors;public int xNumb = 0;	public ShortImageDescription(int size, int part,int hcells, int nColors, boolean allImages,Image []images,int []xoffsets,int []yoffsets){		this.size 			= size;		this.part 			= part;		this.allImages	 	= allImages;		this.images 		= images;		this.xoffsets 		= xoffsets;		this.yoffsets 		= yoffsets;		this.hcells 		= hcells;		this.nColors 		= nColors;		if(images != null && hcells > 0)			xNumb = images.length / hcells;	}}